        Flavor::MpscV3Backoff => run_mpsc_v3_backoff(dur, worker, depth, segments),
    };
    #[cfg(target_os = "linux")]
    let fills = fills.and_then(Fills::finish);
    #[cfg(not(target_os = "linux"))]
