1094	/// The consumer side of a stream from `producers` producers:
1095	/// drain `recv` until each has sent the stop sentinel, asserting
1096	/// each producer's counter order, and return the count received.
1097	///
1098	/// - One producer is [`drain_stream`], so the one-producer cells
1099	///   run what they ran before the producer field.
1100	fn drain_streams(producers: u32, mut recv: impl FnMut() -> u64) -> u64 {
1101	    if producers == 1 {
1102	        return drain_stream(recv);
1103	    }
1104	    let mut next = vec![0u64; producers as usize];
1105	    let (mut stops, mut total) = (0, 0u64);
1106	    while stops < producers {
1107	        let v = recv();
1108	        if v == STOP {
1109	            stops += 1;
1110	            continue;
1111	        }
1112	        let p = (v >> PRODUCER_SHIFT) as usize;
1113	        assert_eq!(
1114	            v & ((1 << PRODUCER_SHIFT) - 1),
1115	            next[p],
1116	            "producer {p}'s order broken"
1117	        );
1118	        next[p] += 1;
1119	        total += 1;
1120	    }
1121	    total
1122	}
